async function applyObs(recalc=false){s.location={name:$("#locName").value||'指定地点',lat:+$("#lat").value,lon:+$("#lon").value,alt:+$("#elev").value||0};const dt=new Date($("#obsTime").value);if(!isNaN(dt))s.time=dt;if(recalc){const ss=A.sunsetForDate(new Date(),s.location.lat,s.location.lon);if(ss)s.time=new Date(ss.getTime()-30*60000)}localStorage.setItem('astrorium_last_location_v1',JSON.stringify(s.location));await A.loadComets(s);await A.loadMeteors(s);send(true);refresh();updateTimeInputs()}$("#applyObs").onclick=()=>applyObs(false);$("#sunsetBtn").onclick=()=>applyObs(true);$("#nowBtn").onclick=()=>{s.time=new Date();send(true);refresh();updateTimeInputs()};$("#syncObsTime").onclick=()=>{$("#obsTime").value=fmt(s.time)};
function nearestPlace(lat,lon){let b=null,bd=1e9;for(const p of window.NICOLE_PLACES||[]){const d=Math.hypot(p.lat-lat,(p.lon-lon)*Math.cos(lat*Math.PI/180));if(d<bd){bd=d;b=p}}return{p:b,d:bd}}
async function fetchElev(lat,lon){const n=nearestPlace(lat,lon);return n.p&&n.d<.3?n.p.alt:NaN}
async function reverseName(lat,lon){const n=nearestPlace(lat,lon);return n.p&&n.d<.5?n.p.name:'任意地点'}
