async function ensureMap(){if(map)return;const host=$("#locationMap");host.innerHTML='';const cv=document.createElement('canvas');cv.style.cssText='width:100%;height:100%;display:block;cursor:crosshair';host.appendChild(cv);map=cv;const draw=()=>{const w=cv.width=cv.clientWidth||600,h=cv.height=cv.clientHeight||320,c=cv.getContext('2d');c.fillStyle='#0b1a2e';c.fillRect(0,0,w,h);c.strokeStyle='rgba(255,255,255,.15)';c.fillStyle='rgba(255,255,255,.5)';c.font='10px sans-serif';for(let lo=-180;lo<=180;lo+=30){const x=(lo+180)/360*w;c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();c.fillText(lo+'°',x+2,h-3)}for(let la=-90;la<=90;la+=30){const y=(90-la)/180*h;c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();c.fillText(la+'°',2,y-2)}c.fillStyle='#8ecbff';for(const p of window.NICOLE_PLACES||[]){c.fillRect((p.lon+180)/360*w-1.5,(90-p.lat)/180*h-1.5,3,3)}if(mapPicked){c.fillStyle='#ff5b5b';c.beginPath();c.arc((mapPicked.lon+180)/360*w,(90-mapPicked.lat)/180*h,5,0,7);c.fill()}};cv.onclick=async e=>{const r=cv.getBoundingClientRect(),lon=(e.clientX-r.left)/r.width*360-180,lat=90-(e.clientY-r.top)/r.height*180,name=await reverseName(lat,lon),elev=await fetchElev(lat,lon);mapPicked={name,lat,lon,alt:Number.isFinite(elev)?elev:0};$("#mapChoice").textContent=`${name} / ${lat.toFixed(2)}, ${lon.toFixed(2)}`;$("#useMap").disabled=false;draw()};map.invalidateSize=draw;draw()}$("#openMap").onclick=()=>{$("#mapModal").classList.add('open');ensureMap();setTimeout(()=>map&&map.invalidateSize(),100)};$("#closeMap").onclick=()=>$("#mapModal").classList.remove('open');$("#useMap").onclick=()=>{if(!mapPicked)return;$("#locName").value=mapPicked.name;$("#lat").value=Number(mapPicked.lat).toFixed(2);$("#lon").value=Number(mapPicked.lon).toFixed(2);$("#elev").value=mapPicked.alt;$("#mapModal").classList.remove('open')};
