function evTime(d){if(!d||isNaN(d))return"—";return`${p2(d.getHours())}:${p2(d.getMinutes())}`}
function renderMoonCalendar(){const y=moonCalBase.getFullYear(),m=moonCalBase.getMonth(),grid=$("#moonCalendar"),today=new Date(),selected=moonSelectedDate;$("#moonMonthLabel").textContent=`${y}年${m+1}月`;const days=new Date(y,m+1,0).getDate(),start=new Date(y,m,1,12).getDay(),prevLast=new Date(y,m,0).getDate(),cells=[];for(let i=0;i<start;i++){const n=prevLast-start+i+1;cells.push({d:new Date(y,m-1,n,12),n,other:true})}for(let n=1;n<=days;n++)cells.push({d:new Date(y,m,n,12),n,other:false});while(cells.length%7) {const n=cells.length-(start+days)+1;cells.push({d:new Date(y,m+1,n,12),n,other:true})}grid.innerHTML=['日','月','火','水','木','金','土'].map(x=>`<div class="mooncal-week">${x}</div>`).join('')+cells.map((c,i)=>{const ph=A.moonPhaseInfo(c.d),it=c.d.toDateString()===today.toDateString(),is=selected&&c.d.toDateString()===selected.toDateString();return`<button class="mooncal-day${c.other?' other':''}${it?' today':''}${is?' selected':''}" data-cal="${i}"><div>${c.n}</div><div class="mooncal-phase">${ph.moonPhase}</div><div class="mooncal-illum">月齢 ${ph.moonAge} / ${ph.moonIllum}%</div></button>`}).join('');grid.querySelectorAll('[data-cal]').forEach(b=>b.onclick=()=>{const c=cells[+b.dataset.cal];moonSelectedDate=new Date(c.d);showMoonDay(moonSelectedDate);openCalendarEventModal(moonSelectedDate);renderMoonCalendar()})}
function openCalendarEventModal(date){const lat=Number($("#lat").value),lon=Number($("#lon").value);if(!Number.isFinite(lat)||!Number.isFinite(lon)){alert("緯度・経度を設定してください。");return}const info=A.calcSkyInfo(lat,lon,date),events=[["日の出",info.sunrise],["日の入り",info.sunset],["薄明開始（朝）",info.astroMorning],["薄明終了（夕）",info.astroEvening],["月の出",info.moonRise],["月の入",info.moonSet]],ph=A.moonPhaseInfo(date);$("#eventModalTitle").textContent=`${date.getFullYear()}年${date.getMonth()+1}月${date.getDate()}日 — 時刻を選択`;$("#eventModalPhase").textContent=`${ph.moonPhase} 月齢 ${ph.moonAge} / 輝面 ${ph.moonIllum}%`;const r=$("#eventList");r.innerHTML=events.map(([n,d],i)=>`<button data-eventpick="${i}" ${d?"":"disabled"}><b>${n}</b><br>${evTime(d)}</button>`).join("");r.querySelectorAll("[data-eventpick]").forEach(b=>b.onclick=()=>{const d=events[+b.dataset.eventpick][1];if(!d)return;s.time=new Date(d);$("#obsTime").value=fmt(s.time);updateTimeInputs();send(true);refresh();$("#calendarEventModal").classList.remove("open")});$("#calendarEventModal").classList.add("open")}
function showMoonDay(date){const lat=Number($("#lat").value),lon=Number($("#lon").value),r=$("#moonCalendarDetail");if(!Number.isFinite(lat)||!Number.isFinite(lon)){r.textContent='緯度・経度を設定してください。';return}const info=A.calcSkyInfo(lat,lon,date),events=[['日の出',info.sunrise],['日の入り',info.sunset],['薄明開始（朝）',info.astroMorning],['薄明終了（夕）',info.astroEvening],['月の出',info.moonRise],['月の入',info.moonSet]],ph=A.moonPhaseInfo(date);r.innerHTML=`<b>${date.getFullYear()}年${date.getMonth()+1}月${date.getDate()}日</b>　${ph.moonPhase} 月齢 ${ph.moonAge} / 輝面 ${ph.moonIllum}%<div class="mooncal-event-grid">${events.map(([n,d],i)=>`<button data-event="${i}" ${d?'':'disabled'}>${n}<br><b>${evTime(d)}</b></button>`).join('')}</div><div class="small muted" style="margin-top:5px">薄明はニコル1と同じ天文薄明（太陽高度 −18°）です。</div>`;r.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{const d=events[+b.dataset.event][1];if(!d)return;$("#obsTime").value=fmt(d);s.time=new Date(d);s.location={name:$("#locName").value||s.location.name,lat:+$("#lat").value,lon:+$("#lon").value,alt:+$("#elev").value||0};send(true);refresh();updateTimeInputs()})}
$("#moonPrev").onclick=()=>{moonCalBase=new Date(moonCalBase.getFullYear(),moonCalBase.getMonth()-1,1);renderMoonCalendar()};$("#moonNext").onclick=()=>{moonCalBase=new Date(moonCalBase.getFullYear(),moonCalBase.getMonth()+1,1);renderMoonCalendar()};$("#moonToday").onclick=()=>{const d=new Date();moonCalBase=new Date(d.getFullYear(),d.getMonth(),1);moonSelectedDate=new Date(d.getFullYear(),d.getMonth(),d.getDate(),12);renderMoonCalendar();showMoonDay(moonSelectedDate)};$("#closeEventModal").onclick=()=>$("#calendarEventModal").classList.remove("open");$("#calendarEventModal").addEventListener("click",e=>{if(e.target===$("#calendarEventModal"))$("#calendarEventModal").classList.remove("open")});

