const SHORTCUT_DEFAULTS=Object.fromEntries(SHORTCUT_ACTIONS.map(x=>[x.id,x.def]));
let shortcuts={...SHORTCUT_DEFAULTS},shortcutCapture=null,locationKeyDirty=false;
try{const v=JSON.parse(localStorage.getItem(SHORTCUT_KEY)||"{}");if(v&&typeof v==="object")shortcuts={...shortcuts,...v}}catch(e){}
function shortcutSignature(e){if(["ShiftLeft","ShiftRight","ControlLeft","ControlRight","AltLeft","AltRight","MetaLeft","MetaRight"].includes(e.code))return"";const a=[];if(e.ctrlKey)a.push("Ctrl");if(e.altKey)a.push("Alt");if(e.shiftKey)a.push("Shift");if(e.metaKey)a.push("Meta");a.push(e.code||e.key);return a.join("+")}
function shortcutLabel(sig){if(!sig)return"未設定";const map={Space:"Space",ArrowLeft:"←",ArrowRight:"→",ArrowUp:"↑",ArrowDown:"↓",NumpadAdd:"テンキー ＋",NumpadSubtract:"テンキー −",Numpad4:"テンキー 4",Numpad6:"テンキー 6",Numpad8:"テンキー 8",Numpad2:"テンキー 2",Numpad7:"テンキー 7",Numpad9:"テンキー 9"};return sig.split("+").map(x=>x==="Meta"?"⌘":x==="Alt"?"Option":x==="Ctrl"?"Control":x==="Shift"?"Shift":map[x]||(x.startsWith("Key")?x.slice(3):x.startsWith("Digit")?x.slice(5):x)).join(" + ")}
function saveShortcuts(){try{localStorage.setItem(SHORTCUT_KEY,JSON.stringify(shortcuts))}catch(e){}}
function renderShortcutEditor(){const root=$("#shortcutGrid");if(!root)return;let group="";root.innerHTML=SHORTCUT_ACTIONS.map(a=>{let h="";if(a.group!==group){group=a.group;h=`<div class="shortcut-section">${esc(group)}</div>`}return h+`<div class="shortcut-action">${esc(a.name)}</div><div class="shortcut-desc">${esc(a.desc)}</div><div><button class="shortcut-bind ${shortcutCapture===a.id?'recording':''}" data-shortcut="${a.id}">${shortcutCapture===a.id?'キーを押してください…':esc(shortcutLabel(shortcuts[a.id]))}</button></div>`}).join("");root.querySelectorAll("[data-shortcut]").forEach(b=>b.onclick=()=>{shortcutCapture=b.dataset.shortcut;renderShortcutEditor()})}
